/// English singular variant of a sentence; `Fn` entries are implemented by
/// `one_fn` in i18n.rs (they carry two independent counts).
pub enum OneSpec {
    Text(&'static str),
    Fn,
}

pub static EN_ONE: &[(&str, OneSpec)] = &[
    ("{n} 台手机", OneSpec::Text("{n} phone")),
    ("{n} 条", OneSpec::Text("{n}")),
    ("{n} 条新短信", OneSpec::Text("{n} new message")),
    ("{n} 条 · 最后一条 {when}", OneSpec::Fn),
    ("{n} 台手机 · {m} 条短信", OneSpec::Fn),
    ("同步完成 · 新增 {n} 条短信", OneSpec::Text("{n} new message synced")),
    ("已导出 {n} 条", OneSpec::Text("Exported {n} message")),
    ("已导出 {n} 条到 CSV", OneSpec::Text("Exported {n} message to CSV")),
    ("本地消息 {n} 条 · 数据目录 {dir}", OneSpec::Text("{n} local message · data folder {dir}")),
    ("正在从 {name} 读取 · 已获取 {n} 条", OneSpec::Text("Reading from {name} · {n} fetched")),
];
